-- Miabe Auto / Neon PostgreSQL. Execute once in Neon SQL Editor.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS postgis;
DO $$ BEGIN CREATE TYPE user_role AS ENUM ('customer','professional','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE establishment_type AS ENUM ('garage','parts_store'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE approval_status AS ENUM ('pending','approved','rejected','suspended'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,full_name text NOT NULL,phone text,role user_role NOT NULL DEFAULT 'customer',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS establishments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid REFERENCES users(id) ON DELETE SET NULL,type establishment_type NOT NULL,name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 160),manager_name text,phone text NOT NULL,whatsapp text,email text,address text NOT NULL,neighborhood text NOT NULL,city text NOT NULL DEFAULT 'Lomé',description text,vehicle_types text[] NOT NULL DEFAULT '{}',specialties text[] NOT NULL DEFAULT '{}',latitude double precision,longitude double precision,location geography(Point,4326),image_url text,opening_hours jsonb NOT NULL DEFAULT '{}'::jsonb,status approval_status NOT NULL DEFAULT 'pending',moderation_note text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE INDEX IF NOT EXISTS establishments_status_idx ON establishments(status);
CREATE INDEX IF NOT EXISTS establishments_owner_idx ON establishments(owner_id);
CREATE INDEX IF NOT EXISTS establishments_geo_idx ON establishments USING GIST(location);
CREATE INDEX IF NOT EXISTS establishments_search_idx ON establishments USING GIN(to_tsvector('simple',coalesce(name,'')||' '||coalesce(address,'')||' '||coalesce(neighborhood,'')||' '||coalesce(city,'')||' '||coalesce(description,'')));
CREATE OR REPLACE FUNCTION set_establishment_location() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.latitude IS NOT NULL AND NEW.longitude IS NOT NULL THEN NEW.location=ST_SetSRID(ST_MakePoint(NEW.longitude,NEW.latitude),4326)::geography; ELSE NEW.location=NULL; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
DROP TRIGGER IF EXISTS establishment_location_trigger ON establishments;
CREATE TRIGGER establishment_location_trigger BEFORE INSERT OR UPDATE OF latitude,longitude ON establishments FOR EACH ROW EXECUTE FUNCTION set_establishment_location();
CREATE TABLE IF NOT EXISTS products(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,name text NOT NULL CHECK(char_length(name) BETWEEN 1 AND 160),category text NOT NULL,vehicle_compatibility text,description text,price_xof integer CHECK(price_xof IS NULL OR price_xof>=0),in_stock boolean NOT NULL DEFAULT true,image_url text,is_active boolean NOT NULL DEFAULT true,updated_at timestamptz NOT NULL DEFAULT now(),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS products_establishment_idx ON products(establishment_id);
CREATE INDEX IF NOT EXISTS products_search_idx ON products USING GIN(to_tsvector('simple',coalesce(name,'')||' '||coalesce(category,'')||' '||coalesce(vehicle_compatibility,'')));
CREATE TABLE IF NOT EXISTS claim_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,requester_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,message text,proof_reference text,status approval_status NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,UNIQUE(establishment_id,requester_id));
CREATE TABLE IF NOT EXISTS reports(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,reporter_id uuid REFERENCES users(id) ON DELETE SET NULL,reason text NOT NULL,status text NOT NULL DEFAULT 'open',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE IF NOT EXISTS favorites(user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,establishment_id uuid NOT NULL REFERENCES establishments(id) ON DELETE CASCADE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(user_id,establishment_id));
CREATE TABLE IF NOT EXISTS audit_logs(id bigserial PRIMARY KEY,actor_id uuid REFERENCES users(id) ON DELETE SET NULL,action text NOT NULL,target_type text NOT NULL,target_id uuid,details jsonb,created_at timestamptz NOT NULL DEFAULT now());
